verifyCmd:
node <<'VERIFYJS'
const { flatten, unflatten } = require('./flatten.js');
const S = JSON.stringify;
const eq = (got, want, m) => { if (S(got) !== S(want)) { console.error('FAIL', m, S(got), 'want', S(want)); process.exit(1); } };
eq(flatten({ a: { b: 1 } }), { 'a.b': 1 }, 'nested');
eq(flatten({ a: [1, 2] }), { 'a.0': 1, 'a.1': 2 }, 'array index');
eq(flatten({ a: [{ b: 3 }] }), { 'a.0.b': 3 }, 'array of objects');
eq(flatten({ a: {} }), { a: {} }, 'empty object preserved as leaf');
eq(flatten({ a: [] }), { a: [] }, 'empty array preserved as leaf');
eq(flatten({ a: null }), { a: null }, 'null is a leaf');
eq(flatten({ 'x.y': 1 }), { 'x\\.y': 1 }, 'dot in key escaped');
eq(unflatten({ 'a.b': 1 }), { a: { b: 1 } }, 'unflatten nested');
eq(unflatten({ 'a.0': 1, 'a.1': 2 }), { a: [1, 2] }, 'rebuilds array');
eq(unflatten({ 'x\\.y': 1 }), { 'x.y': 1 }, 'unescapes dot');
eq(unflatten({ 'a.1': 'x' }), { a: { 1: 'x' } }, 'gapped keys stay an object');
for (const v of [
  { a: { b: { c: 1 } } }, { a: [1, [2, 3]] }, { a: {}, b: [] }, { 'k.1': { 'm.2': 5 } },
  { list: [{ id: 1 }, { id: 2 }] }, { mixed: { 0: 'a', 2: 'b' } }, { deep: { a: [{ b: [1] }] } },
]) {
  const round = unflatten(flatten(v));
  if (S(round) !== S(v)) { console.error('round-trip failed', S(v), '->', S(round)); process.exit(1); }
}
console.log('ok');
VERIFYJS
